      <input
        ref={fileRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) void onFile(f);
        }}
      />

      {phase !== "confirm" && (
        <>
          <Kicker className="mb-[10px] block">Add a piece</Kicker>
          <h1 className="mb-6 font-serif text-3xl/[1.12] text-foreground">
            Capture an item.
