input.script:
export const meta = {
  name: 'review-generator-handoff',
  description: 'Review the Claude Design handoff for the Fitcheck outfit generator (v2 authoritative design)',
  phases: [
    { title: 'Review', detail: 'four independent lenses on the v2 design + README spec' },
    { title: 'Synthesize', detail: 'per-file verdict + v2 assessment + implementation plan' },
  ],
}

const HAND = '/Users/1curafu/Desktop/Fitcheck/Fitcheck/design_handoff_stylist_generator'
const V2 = `${HAND}/generator-mockup-v2.html`
const ORIG = `${HAND}/generator-mockup-original.html`
const README = `${HAND}/README.md`
const PRODUCT = '/Users/1curafu/Desktop/Fitcheck/Fitcheck/PRODUCT.md'
const DESIGN = '/Users/1curafu/Desktop/Fitcheck/Fitcheck/DESIGN.md'

const STACK = [
  'TARGET APP (what this will be implemented in): Next.js 16 App Router, React 19, TypeScript, Tailwind v4.',
  'The "Midnight Atelier" design tokens ALREADY EXIST in the codebase as Tailwind/CSS custom properties (canvas #0E0E10, cream/foreground #EDE6D8, brand/rust #B86A47, surface-1 #161517, muted-foreground #928C7F, muted-dim #615C52, etc.) — fonts Libre Caslon Text + Hanken Grotesk are wired.',
  'Animation via the `motion` library (motion/react). Data via Supabase (RLS). It is a mobile-first PWA, NOT React Native/Swift/Flutter — plain React web.',
  'The generator screen target is app/generate/page.tsx (currently a "coming soon" placeholder).',
  'Plan 06 defines the generator pipeline: SQL rules filter -> TS scoring -> Claude Haiku 4.5 text-only re-rank returning top 3 outfits + a one-sentence "why". Weather = Open-Meteo (hourly, free, no key). Location = browser Geolocation + a city override. Garments render as background-removed PNG cutouts (alpha) of the user\u2019s own clothes.',
].join('\n')

const FACTS = [
  'Established facts (do not re-derive): design_handoff/Fitcheck.dc.html is BYTE-IDENTICAL to the full 12-screen prototype already in the repo at styling/project/Fitcheck.dc.html (a pure duplicate; its Generate tab is the OLD pre-revision variant).',
  'generator-mockup-original.html is byte-identical to the mockup we (the implementers) originally handed to Claude Design — the pre-review version.',
  'generator-mockup-v2.html is Claude Design\u2019s revision (~306 changed lines) and is the AUTHORITATIVE design. README.md is its written spec.',
].join('\n')

const REVIEW_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    dimension: { type: 'string' },
    verdict: { type: 'string', description: 'one-line bottom line for this lens' },
    score: { type: ['number', 'null'], description: '0-10 if this lens scores; else null' },
    strengths: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { point: { type: 'string' }, detail: { type: 'string' } }, required: ['point', 'detail'] } },
    concerns: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { point: { type: 'string' }, detail: { type: 'string' }, severity: { type: 'string', enum: ['high', 'medium', 'low'] } }, required: ['point', 'detail', 'severity'] } },
    notes: { type: 'string' },
  },
  required: ['dimension', 'verdict', 'score', 'strengths', 'concerns', 'notes'],
}

const DIMS = [
  {
    key: 'design-brand',
    prompt: `You are a senior product-design director reviewing a finalized app screen for DESIGN QUALITY and BRAND FIT.\n\nRead: ${V2} (the authoritative design — a desktop review page: phone mockup on the left, annotation panel on the right), ${README} (its written spec), ${PRODUCT} and ${DESIGN} (brand + design system).\n\nJudge the generator ("Stylist") screen in v2. Is it genuinely good? Score it /10. Assess how well it holds the brand: Midnight Atelier (cream on near-black), EDITORIAL / quiet-luxury / "modern preppy" (SSENSE / Mr Porter), "let the clothes be the hero" (cutouts + flat-lay collage), the italic one-sentence "why" as the HERO text (the product differentiator), and the ANTI-references (not gamified, not a SaaS dashboard, no generic-AI look). Evaluate hierarchy, typography, spacing/rhythm, the flat-lay art direction, the "why" treatment, the header density (title + weather + city + Later + occasion chips + Refine), and the credits line. You can reason from the HTML/CSS + the spec; you do not need to see it rendered.\n\n${FACTS}\n\nReturn structured output: set score to your /10. strengths = the strongest calls; concerns = anything weak/off-brand/cluttered with severity. Be specific and honest.`,
  },
  {
    key: 'changes-vs-original',
    prompt: `You are reviewing what changed between two revisions of the same screen and whether each change is an IMPROVEMENT or a REGRESSION.\n\nRead BOTH: ${ORIG} (the original/pre-review version) and ${V2} (Claude Design\u2019s revision). Also read ${README} which lists the intended changes (unboxed the weather pill; credits changed from boxed thumbnail tiles to a single magazine-style text line; flat-lay went from grid-aligned to art-directed — rotated 2-8 degrees, real garment overlap, per-look composition; the "Dressed for" cell was merged into the "Later" advice line).\n\nGo through the concrete differences (structure, weather treatment, credits, flat-lay, advice voice, header). For EACH material change, decide better / worse / neutral and say why against the brand (editorial, clothes-as-hero, why-as-hero, uncluttered). Flag anything Claude Design got WORSE or lost from the original.\n\n${FACTS}\n\nReturn structured output. score = your overall /10 for "is v2 a net improvement over the original" (10 = clearly better). Put each change as a strength (improvement) or concern (regression/loss) with a clear detail; use notes for neutral changes.`,
  },
  {
    key: 'implementation-readiness',
    prompt: `You are a senior React engineer assessing whether this design handoff is READY TO IMPLEMENT in the actual target codebase, and estimating effort + risks.\n\nTARGET STACK:\n${STACK}\n\nRead: ${README} (the spec — very detailed, has tokens, states, interactions, state-management notes) and ${V2} (the interactive prototype). Assess: (1) completeness — is there enough to build pixel-accurately, or are there gaps/ambiguities? (2) mapping to our stack — the tokens already exist; the prototype is vanilla HTML/CSS/JS, so what has to be re-expressed in React + Tailwind + motion? (3) the hard parts — the per-look flat-lay layout templates (x/y/w/h/rotation/z per garment cutout), the re-lay stagger animation (45ms/piece, quote +120ms, credits +200ms), the city dropdown, the Later hourly expand, the Refine bottom sheet, swipe-to-page; (4) integration seams with Plan 06 (generator pipeline output shape vs the README\u2019s looks[3] model, Open-Meteo hourly, geolocation + city override, garment cutout URLs + per-look layout). Flag anything in the spec that fights our stack or that is under-specified for production (e.g. where do per-look layout templates come from? how many templates? what if a look has 3 vs 5 pieces?).\n\n${FACTS}\n\nReturn structured output. score = /10 implementation-readiness (10 = build it straight from this). strengths = what makes it easy; concerns = gaps, ambiguities, hard parts, and integration risks with severity. notes = a rough effort read.`,
  },
  {
    key: 'critic',
    prompt: `You are an adversarial design critic. Your job is to argue the CASE AGAINST v2 and find every real problem — do not praise. Assume the team is about to build this and you are the last check.\n\nRead: ${V2}, ${README}, ${PRODUCT}, ${DESIGN}.\n\nHunt for: off-brand moves; anything that reads as generic-AI or SaaS-utility; header OVERLOAD (does the top do too much: title + date + weather + city + Later + occasion chips + Refine all stacked above the hero?); the credits text line being hard to scan or fighting the editorial calm; the flat-lay overlap risking a messy/cluttered pile instead of a composed collage; the "why" losing prominence to all the chrome above it; accessibility problems (contrast on muted-dim/faint text, touch targets, the tiny 9-10px tracked-caps labels, the credits line tap targets); interaction ambiguities (two paging affordances: 01/02/03 index AND swipe; occasion regenerate vs look paging confusion); reduced-motion; and whether the screen truly fits "phone, morning, decide fast" or is over-featured for a daily glance. Be specific with the worst offenders.\n\n${FACTS}\n\nReturn structured output. score = /10 where 10 means "you found no real problems" (low score = many real problems). Put every real problem in concerns with severity; strengths may be empty or minimal. Be tough but fair — only real issues, no nitpicks dressed as blockers.`,
  },
]

phase('Review')
const reviews = (await parallel(
  DIMS.map((d) => () => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: REVIEW_SCHEMA }))
)).filter(Boolean)

phase('Synthesize')
const SYNTH_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    fileVerdicts: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          file: { type: 'string' },
          whatItIs: { type: 'string' },
          need: { type: 'string', enum: ['implement', 'reference-keep', 'redundant-discard'] },
          reason: { type: 'string' },
        },
        required: ['file', 'whatItIs', 'need', 'reason'],
      },
    },
    v2Score: { type: 'number' },
    v2Verdict: { type: 'string' },
    holdsBrand: { type: 'boolean' },
    netImprovementOverOriginal: { type: 'boolean' },
    topStrengths: { type: 'array', items: { type: 'string' } },
    topConcerns: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { concern: { type: 'string' }, severity: { type: 'string', enum: ['high', 'medium', 'low'] }, recommendation: { type: 'string' } }, required: ['concern', 'severity', 'recommendation'] } },
    keyChanges: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { change: { type: 'string' }, verdict: { type: 'string', enum: ['better', 'worse', 'neutral'] } }, required: ['change', 'verdict'] } },
    implementation: {
      type: 'object', additionalProperties: false,
      properties: {
        readinessScore: { type: 'number' },
        effort: { type: 'string' },
        hardParts: { type: 'array', items: { type: 'string' } },
        integrationRisks: { type: 'array', items: { type: 'string' } },
        specGaps: { type: 'array', items: { type: 'string' } },
      },
      required: ['readinessScore', 'effort', 'hardParts', 'integrationRisks', 'specGaps'],
    },
    recommendation: { type: 'string' },
    openQuestionsForUser: { type: 'array', items: { type: 'string' } },
  },
  required: ['fileVerdicts', 'v2Score', 'v2Verdict', 'holdsBrand', 'netImprovementOverOriginal', 'topStrengths', 'topConcerns', 'keyChanges', 'implementation', 'recommendation', 'openQuestionsForUser'],
}

const synthesis = await agent(
  `You are the review lead. Four independent reviewers assessed the Claude Design handoff for the Fitcheck outfit generator. Synthesize ONE coherent review.\n\n${FACTS}\n\nThe four files in the bundle are: README.md, generator-mockup-v2.html (authoritative design), generator-mockup-original.html (pre-review dup of our own mockup), Fitcheck.dc.html (byte-identical dup of styling/project/Fitcheck.dc.html already in repo).\n\nReviewer outputs (JSON):\n${JSON.stringify(reviews, null, 1)}\n\nProduce the final structured review. fileVerdicts MUST cover all four files with a need of implement / reference-keep / redundant-discard and a reason (remember two files are exact duplicates already in the repo). Reconcile the design-quality reviewers with the adversarial critic into an honest v2Score and topConcerns (dedupe, keep the real ones, attach a recommendation to each). keyChanges = the material v2-vs-original changes with a better/worse/neutral verdict. implementation = readiness for the Next.js React stack with effort, hardParts, integrationRisks, specGaps. recommendation = the bottom-line next step. openQuestionsForUser = genuine decisions the user must make.`,
  { label: 'synthesize', phase: 'Synthesize', schema: SYNTH_SCHEMA }
)

return { reviews, synthesis }

