122	
123	### Task 3: Colour harmony (TDD — strict)
124	
125	**Files:** Test `lib/generator/__tests__/color.test.ts`; create `lib/generator/color.ts`.
126	
127	- [ ] **Step 1: Failing tests**
128	
129	```ts
130	// lib/generator/__tests__/color.test.ts
131	import { isNeutral, colorHarmonyScore } from "../color";
132	
133	test("classifies neutrals vs accents", () => {
134	  expect(isNeutral("navy")).toBe(true);
135	  expect(isNeutral("Cream")).toBe(true);    // case-insensitive
136	  expect(isNeutral("rust")).toBe(false);
137	});
138	test("an all-neutral outfit scores higher than a multi-accent one", () => {
139	  expect(colorHarmonyScore(["navy", "cream", "brown"]))
140	    .toBeGreaterThan(colorHarmonyScore(["rust", "olive", "camel"]));
141	});
142	test("a single accent on neutrals is fine (>= 0.8)", () => {
143	  expect(colorHarmonyScore(["navy", "cream", "rust"])).toBeGreaterThanOrEqual(0.8);
144	});
145	test("score is clamped to 0..1", () => {
146	  const s = colorHarmonyScore(["rust", "olive", "camel", "navy"]);
147	  expect(s).toBeGreaterThanOrEqual(0);
148	  expect(s).toBeLessThanOrEqual(1);
149	});
150	```
151	
152	- [ ] **Step 2: Run → FAIL.**
153	
154	- [ ] **Step 3: Implement** (spec §7 rule table: neutrals pair with anything; each extra accent penalized)
155	
156	```ts
157	// lib/generator/color.ts
158	const NEUTRALS = new Set([
159	  "navy","grey","gray","beige","white","black","brown","cream","tan","stone","charcoal","khaki","ecru",
160	]);
161	export function isNeutral(color: string): boolean {
162	  return NEUTRALS.has(color.trim().toLowerCase());
163	}
164	/** 1.0 = all neutral; each accent beyond the first costs 0.25. */
165	export function colorHarmonyScore(colors: string[]): number {
166	  const accents = colors.filter((c) => !isNeutral(c)).length;
167	  const penalty = Math.max(0, accents - 1) * 0.25;
168	  return Math.min(1, Math.max(0, 1 - penalty));
169	}
