215	```ts
216	// lib/generator/score.ts
217	import { colorHarmonyScore } from "./color";
218	
219	export type ScoreItem = {
220	  category: string; colors: string[]; formality: number | null; style_tags?: string[];
221	};
222	export type Ctx = { aesthetic: string[]; band: [number, number] };
223	
224	/** 1.0 = identical formality; falls off with spread. */
225	export function formalityCoherence(formalities: number[]): number {
226	  const f = formalities.filter((x) => typeof x === "number");
227	  if (f.length < 2) return 1;
228	  const spread = Math.max(...f) - Math.min(...f);
229	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
230	}
231	
232	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
233	  const colors = items.flatMap((i) => i.colors);
234	  const harmony = colorHarmonyScore(colors);
235	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
236	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
237	  const dna = items.length ? dnaHits / items.length : 0;
238	  return Math.min(1, 0.45 * harmony + 0.35 * coherence + 0.2 * dna);
239	}
240	```
