288	```ts
289	// lib/generator/candidates.ts
290	import { occasionBand, weatherRules, type Occasion, type Weather } from "./rules";
291	
292	type Item = {
293	  id: string; category: string; colors: string[]; formality: number | null;
294	  seasons: string[]; material: string | null; style_tags?: string[];
295	};
296	type Args = {
297	  occasion: Occasion; weather: Weather; season: string;
298	  aesthetic: string[]; excludeItemIds: string[];
299	};
300	
301	export function buildCandidates(items: Item[], a: Args): Item[][] {
302	  const [lo, hi] = occasionBand(a.occasion);
303	  const { needsOuterwear, excludeMaterials } = weatherRules(a.weather);
304	
305	  const eligible = items.filter((i) => {
306	    if (a.excludeItemIds.includes(i.id)) return false;
307	    if (i.material && excludeMaterials.includes(i.material.toLowerCase())) return false;
308	    if (i.seasons.length && !i.seasons.includes(a.season)) return false;
309	    const f = i.formality ?? 3;
310	    return f >= lo - 0.5 && f <= hi + 0.5;
311	  });
312	
313	  const byCat = (c: string) => eligible.filter((i) => i.category === c);
314	  const tops = byCat("top"), bottoms = byCat("bottom"), shoes = byCat("shoes");
315	  const outer = needsOuterwear ? byCat("outerwear") : [];
316	
317	  const combos: Item[][] = [];
318	  for (const t of tops) for (const b of bottoms) for (const s of shoes) {
319	    const base = [t, b, s];
320	    if (needsOuterwear && outer.length) combos.push([...base, outer[0]]);
321	    else combos.push(base);
322	  }
323	  return combos;
324	}
325	```
