455	// lib/generator/rerank.ts
456	"use server";
457	import Anthropic from "@anthropic-ai/sdk";
458	import { z } from "zod";
459	
460	type DescItem = { category: string; subcategory?: string | null; colors: string[] };
461	
462	export function describeCombos(combos: DescItem[][]): string {
463	  return combos.map((c, i) =>
464	    `${i}. ` + c.map((it) => `${it.subcategory ?? it.category} (${it.colors.join("/")})`).join(" + ")
465	  ).join("\n");
466	}
467	
468	export const RerankSchema = z.object({
469	  picks: z.array(z.object({ combo_index: z.number().int(), reasoning: z.string().min(1) })).length(3),
470	});
471	
472	const client = new Anthropic();
473	
474	export async function rerank(args: {
475	  combos: DescItem[][]; aesthetic: string[]; occasion: string; weatherLabel: string; tempC: number;
476	}) {
477	  const prompt =
478	`You are a personal stylist. The user's aesthetic is ${args.aesthetic.join(", ")}. \
479	Occasion: ${args.occasion}. Weather: ${args.weatherLabel}, ${args.tempC}°C.
480	Here are candidate outfits (already filtered & scored):
481	${describeCombos(args.combos)}
482	
483	Pick the best 3. For each, give ONE warm, specific sentence on why it works \
484	(reference colours/pieces, like "the camel knit warms the grey trousers and picks up the loafers"). \
485	Return their indices.`;
486	
487	  const res = await client.messages.create({
488	    model: "claude-haiku-4-5",
489	    max_tokens: 600,
490	    output_config: { format: { type: "json_schema", schema: z.toJSONSchema(RerankSchema) } },
491	    messages: [{ role: "user", content: prompt }],
492	  });
493	  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
494	  return RerankSchema.parse(JSON.parse(text));
495	}
