```ts
// lib/generator/candidates.ts
import { occasionBand, weatherRules, type Occasion, type Weather } from "./rules";

type Item = {
  id: string; category: string; colors: string[]; formality: number | null;
  seasons: string[]; material: string | null; style_tags?: string[];
};
type Args = {
  occasion: Occasion; weather: Weather; season: string;
  aesthetic: string[]; excludeItemIds: string[];
};

export function buildCandidates(items: Item[], a: Args): Item[][] {
  const [lo, hi] = occasionBand(a.occasion);
  const { needsOuterwear, excludeMaterials } = weatherRules(a.weather);

  const eligible = items.filter((i) => {
    if (a.excludeItemIds.includes(i.id)) return false;
    if (i.material && excludeMaterials.includes(i.material.toLowerCase())) return false;
    if (i.seasons.length && !i.seasons.includes(a.season)) return false;
    const f = i.formality ?? 3;
    return f >= lo - 0.5 && f <= hi + 0.5;
  });

  const byCat = (c: string) => eligible.filter((i) => i.category === c);
  const tops = byCat("top"), bottoms = byCat("bottom"), shoes = byCat("shoes");
  const outer = needsOuterwear ? byCat("outerwear") : [];

  const combos: Item[][] = [];
  for (const t of tops) for (const b of bottoms) for (const s of shoes) {
    const base = [t, b, s];
    if (needsOuterwear && outer.length) combos.push([...base, outer[0]]);
    else combos.push(base);
  }
  return combos;
}
```

