// lib/weather/open-meteo.ts
const RAIN_CODES = new Set([51,53,55,61,63,65,80,81,82,95,96,99]);
type Raw = { current: { temperature_2m: number; weather_code: number } };

export function mapForecast(raw: Raw) {
  const code = raw.current.weather_code;
  return {
    tempC: Math.round(raw.current.temperature_2m),
    rain: RAIN_CODES.has(code),
    label: RAIN_CODES.has(code) ? "Rain" : code === 0 ? "Clear" : "Overcast",
  };
}

export async function fetchWeather(lat: number, lon: number) {
  const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code`;
  const res = await fetch(url, { next: { revalidate: 1800 } });
  return mapForecast(await res.json());
}
