```ts
// lib/generator/rerank.ts
"use server";
import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";

type DescItem = { category: string; subcategory?: string | null; colors: string[] };

export function describeCombos(combos: DescItem[][]): string {
  return combos.map((c, i) =>
    `${i}. ` + c.map((it) => `${it.subcategory ?? it.category} (${it.colors.join("/")})`).join(" + ")
  ).join("\n");
}

export const RerankSchema = z.object({
  picks: z.array(z.object({ combo_index: z.number().int(), reasoning: z.string().min(1) })).length(3),
});

const client = new Anthropic();

export async function rerank(args: {
  combos: DescItem[][]; aesthetic: string[]; occasion: string; weatherLabel: string; tempC: number;
}) {
  const prompt =
`You are a personal stylist. The user's aesthetic is ${args.aesthetic.join(", ")}. \
Occasion: ${args.occasion}. Weather: ${args.weatherLabel}, ${args.tempC}°C.
Here are candidate outfits (already filtered & scored):
${describeCombos(args.combos)}

Pick the best 3. For each, give ONE warm, specific sentence on why it works \
(reference colours/pieces, like "the camel knit warms the grey trousers and picks up the loafers"). \
Return their indices.`;

  const res = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 600,
    output_config: { format: { type: "json_schema", schema: z.toJSONSchema(RerankSchema) } },
    messages: [{ role: "user", content: prompt }],
  });
  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
  return RerankSchema.parse(JSON.parse(text));
}
```

