```ts
// app/(app)/generate/actions.ts
"use server";
import { createClient } from "@/lib/supabase/server";
import { fetchWeather } from "@/lib/weather/open-meteo";
import { buildCandidates } from "@/lib/generator/candidates";
import { rankTopN } from "@/lib/generator/rank";
import { occasionBand, type Occasion } from "@/lib/generator/rules";
import { rerank } from "@/lib/generator/rerank";

export async function generate(occasion: Occasion) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("Not authenticated");

  const { data: profile } = await supabase.from("profiles")
    .select("style_aesthetic, location_lat, location_lon").eq("id", user.id).single();
  const { data: items = [] } = await supabase.from("items").select("*").eq("archived", false);

  const weather = await fetchWeather(profile?.location_lat ?? 51.5, profile?.location_lon ?? -0.12);
  const season = currentSeason();

  const combos = buildCandidates(items, {
    occasion, weather, season, aesthetic: profile?.style_aesthetic ?? [], excludeItemIds: [],
  });
  if (combos.length === 0) return { weather, looks: [], empty: true };

  const top = rankTopN(combos, { aesthetic: profile?.style_aesthetic ?? [], band: occasionBand(occasion) }, 20);
  const { picks } = await rerank({
    combos: top.map((t) => t.items as any), aesthetic: profile?.style_aesthetic ?? [],
    occasion, weatherLabel: weather.label, tempC: weather.tempC,
  });

  const looks = picks.map((p) => ({ items: top[p.combo_index].items, reasoning: p.reasoning }));
  return { weather, looks, empty: false };
}

function currentSeason(): string {
  const m = new Date().getMonth(); // 0..11
  return m < 2 || m === 11 ? "winter" : m < 5 ? "spring" : m < 8 ? "summer" : "autumn";
}
```

