// lib/generator/__tests__/layout.test.ts
import { layoutForLook } from "../layout";
const pcs = (cats: string[]) => cats.map((category, i) => ({ itemId: `i${i}`, category }));

test("returns a slot per piece for 3/4/5-piece looks", () => {
  for (const n of [3,4,5]) {
    const cats = ["Tops","Bottoms","Shoes","Outerwear","Accessories"].slice(0,n);
    expect(layoutForLook(pcs(cats))).toHaveLength(n);
  }
});
test("every slot stays fully inside the stage (no clip): 0 ≤ x, x+w ≤ 100; same for y/h", () => {
  const slots = layoutForLook(pcs(["Tops","Bottoms","Shoes","Outerwear","Accessories"]));
  for (const s of slots) {
    expect(s.xPct).toBeGreaterThanOrEqual(0);
    expect(s.yPct).toBeGreaterThanOrEqual(0);
    expect(s.xPct + s.wPct).toBeLessThanOrEqual(100);
    expect(s.yPct + s.hPct).toBeLessThanOrEqual(100);
  }
});
test("rotation is bounded to ±6° (D6)", () => {
  for (const s of layoutForLook(pcs(["Tops","Bottoms","Shoes","Outerwear"])))
    expect(Math.abs(s.rotationDeg)).toBeLessThanOrEqual(6);
});
test("the anchor (outerwear if present, else top) has the highest z and is first in stagger order", () => {
  const withOuter = layoutForLook(pcs(["Tops","Bottoms","Shoes","Outerwear"]));
  const outer = withOuter[3]; // Outerwear
  expect(Math.max(...withOuter.map(s => s.z))).toBe(outer.z);
  const noOuter = layoutForLook(pcs(["Tops","Bottoms","Shoes"]));
  const top = noOuter[0];
  expect(Math.max(...noOuter.map(s => s.z))).toBe(top.z);
});
test("deterministic: same categories in same order → identical slots", () => {
  const a = layoutForLook(pcs(["Tops","Bottoms","Shoes"]));
  const b = layoutForLook(pcs(["Tops","Bottoms","Shoes"]));
  expect(a).toEqual(b);
});
test("the anchor is the largest slot by area", () => {
  const slots = layoutForLook(pcs(["Tops","Bottoms","Shoes","Outerwear"]));
  const area = (s: {wPct:number;hPct:number}) => s.wPct*s.hPct;
  const anchor = slots[3];
  for (const s of slots) expect(area(anchor)).toBeGreaterThanOrEqual(area(s));
});

