  expect(() =>
    TagSchema.parse({
      category: "Hat",
      subcategory: "x",
      colors: ["red"],
      pattern: "solid",
      material: "wool",
      formality: 2,
      seasons: ["Winter"],
    }),
  ).toThrow();
});

